Proof.
  intros segs ca ONE id C g m GL CS.
  destruct GL as [(_ & SW & IDB & _ & idpad & pP & pA & pB & pX & pY & pZ & pN & hpad & ->)
              |[(_ & ID913 & idpad & pP & pA & pB & pX & pY & pZ & pN & hpad & PA & PX & PZ & wA & wX & wZ & -> & _)
              |[(R0 & _)|(R0 & _)]]].
  - flat constr:((grp_sw_checks segs (ca id) ONE id m C idpad pP pA pB pX pY pZ pN hpad CS SW IDB)) 9%nat. intros H1 X0 Y0 SP SA SB VP SGP NOH.
    refine (conj SGP (conj _ (conj _ (conj SP (conj SA (conj SB (conj VP _))))))).
    + exact (grp_sw_point_read_facts segs (ca id) ONE id m C idpad pP pA pB pX pY pZ pN hpad CS SW IDB).
    + left. auto.
    + intros d Hd O. exfalso. exact (proj1 (Forall_forall _ _) NOH d Hd O).
  - flat constr:((grp_mx_checks (ca id) id C idpad pP pA pB pX pY pZ pN hpad PA PX PZ wA wX wZ ID913)) 8%nat. intros H2 Y0 SP SA SB VP SGP HL.
    refine (conj SGP (conj _ (conj _ (conj SP (conj SA (conj SB (conj VP _))))))).
    + exact (grp_mx_point_read_facts (ca id) id C idpad pP pA pB pX pY pZ pN hpad PA PX PZ wA wX wZ ID913).
    + right. auto.
    + intros d Hd O. destruct (HL d Hd O) as [[_ N]|[[_ N]|[_ N]]]; exact N.
  - exfalso. unfold MBEDTLS_ERR_ECP_FEATURE_UNAVAILABLE in R0. lia.
  - exfalso. unfold MBEDTLS_ERR_MPI_ALLOC_FAILED in R0. lia.
Qed.

